import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Global damage and Local Trauma","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/damage.md","filePath":"game-design/combat/damage.md"}'),o={name:"game-design/combat/damage.md"};function r(l,e,s,d,m,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="global-damage-and-local-trauma" tabindex="-1">Global damage and Local Trauma <a class="header-anchor" href="#global-damage-and-local-trauma" aria-label="Permalink to &quot;Global damage and Local Trauma&quot;">​</a></h1><p><strong>Design status: Accepted separation and experimental formula. Implementation: Stage 2A natural melee absorption, HP/lifecycle gate and live local-state commit; gameplay validation pending.</strong></p><p>Global damage reduces Hits and drives existing death/loot. Local Trauma reduces functional integrity in the actual region. Armor conceptually protects against both, but these are separate results; neither local integrity nor a UI number replaces global health.</p><h3 id="accepted-experimental-lab-policy" tabindex="-1">Accepted experimental Lab policy <a class="header-anchor" href="#accepted-experimental-lab-policy" aria-label="Permalink to &quot;Accepted experimental Lab policy&quot;">​</a></h3><p>Capture residual damage after shield, selected armor, virtual and melee magical mitigation, <strong>before</strong> the legacy global minimum of one. Candidate trauma is <code>min(100, 2 × max(0, residual))</code>; saturate before multiplication. Applied trauma is capped by remaining region integrity. Residual 12 proposes 24 trauma, not necessarily 12 HP lost.</p><p>Commit only if the defender is still alive in the same lifecycle and the hit actually lost positive HP. A minimum-one global hit with zero residual has zero trauma. A lethal hit follows existing death/loot and skips late live-body updates/stow. Actual Hits lost must be measured around the damage event before later effects; a damage routine’s return value alone is not a reliable measurement.</p><p>These numeric and gating policies are Accepted for the prototype, not final balance. The experiment captures residual damage before the minimum-one floor and immediate HP loss, validates living supported participants and unchanged body state, and resolves the actual contact once before applying trauma. <strong>Gap:</strong> runtime comparisons remain unverified. Materials and independently tuned global/local mitigation are future work.</p><h2 id="proposed-equipment-quality-interactions" tabindex="-1">Proposed equipment-quality interactions <a class="header-anchor" href="#proposed-equipment-quality-interactions" aria-label="Permalink to &quot;Proposed equipment-quality interactions&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">Itemization &amp; Craft Quality</a> proposes compact weapon-quality dimensions, material/process tradeoffs and rare traits. Its threshold, penetration and functional-wear examples do not replace the experimental residual ×2 policy above. <a href="/Syrolands-Public/game-design/professions/alchemy.html">Alchemy</a> proposes distinct relief/support interactions; bleeding, pain and other future consequences are not implemented by documenting them.</p><h2 id="proposed-injuries-and-healing" tabindex="-1">Proposed injuries and Healing <a class="header-anchor" href="#proposed-injuries-and-healing" aria-label="Permalink to &quot;Proposed injuries and Healing&quot;">​</a></h2><p>Global health, regional integrity, armor condition and future bleeding are distinct concerns. <a href="/Syrolands-Public/game-design/combat/weapons-and-damage.html">Weapon families</a> and <a href="/Syrolands-Public/game-design/combat/armor-and-mitigation.html">material interactions</a> may eventually produce differentiated wounds, functional weaknesses and tactical information. None replaces the accepted experimental formula above.</p><p>Healing could address bleeding, trauma, local injury, stabilization and recovery rather than only Hits. Exact treatment, thresholds, persistence and timing remain Unresolved. Ordinary HP healing does not automatically restore integrity under the <a href="/Syrolands-Public/game-design/combat/body-regions.html">current lifecycle</a>; the proposed medical direction does not change Lab resets or add passive recovery. Other functional penalties remain outside the <a href="/Syrolands-Public/game-design/combat/disability.html">accepted shield consequence</a>.</p><p><a href="/Syrolands-Public/guide/combat/limbs-and-trauma.html">Player guide: Limbs and Trauma</a>.</p>',13)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
